// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /api/health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)

	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)

	// (GET /api/v1/auth/{provider})
	AuthDetails(ctx context.Context, request AuthDetailsRequestObject) (AuthDetailsResponseObject, error)

	// (POST /api/v1/auth/{provider}/callback)
	AuthCallback(ctx context.Context, request AuthCallbackRequestObject) (AuthCallbackResponseObject, error)

	// (POST /api/v1/connectors/onboarding-requests)
	OnboardConnector(ctx context.Context, request OnboardConnectorRequestObject) (OnboardConnectorResponseObject, error)

	// (GET /api/v1/connectors/onboarding-requests/{onboarding-id})
	GetConnectorOnboardingRequestDetails(ctx context.Context, request GetConnectorOnboardingRequestDetailsRequestObject) (GetConnectorOnboardingRequestDetailsResponseObject, error)

	// (GET /api/v1/managed-systems)
	ListManagedSystems(ctx context.Context, request ListManagedSystemsRequestObject) (ListManagedSystemsResponseObject, error)

	// (POST /api/v1/managed-systems)
	OnboardManagedSystem(ctx context.Context, request OnboardManagedSystemRequestObject) (OnboardManagedSystemResponseObject, error)

	// (GET /api/v1/managed-systems/{id})
	GetManagedSystem(ctx context.Context, request GetManagedSystemRequestObject) (GetManagedSystemResponseObject, error)

	// (GET /api/v1/managed-systems/{id}/tenant)
	ListManagedSystemTenants(ctx context.Context, request ListManagedSystemTenantsRequestObject) (ListManagedSystemTenantsResponseObject, error)

	// (POST /api/v1/managed-systems/{id}/tenant)
	OnboardManagedSystemTenant(ctx context.Context, request OnboardManagedSystemTenantRequestObject) (OnboardManagedSystemTenantResponseObject, error)

	// (GET /api/v1/users)
	GetUserDetails(ctx context.Context, request GetUserDetailsRequestObject) (GetUserDetailsResponseObject, error)

	// (POST /api/v1/workflows)
	CreateWorkflow(ctx context.Context, request CreateWorkflowRequestObject) (CreateWorkflowResponseObject, error)

	// (GET /api/v1/workflows/{name})
	GetWorkflow(ctx context.Context, request GetWorkflowRequestObject) (GetWorkflowResponseObject, error)

	// (POST /api/v1/workflows/{name}/runs)
	StartWorkflow(ctx context.Context, request StartWorkflowRequestObject) (StartWorkflowResponseObject, error)

	// (GET /api/v1/workflows/{name}/runs/{id})
	GetWorkflowRun(ctx context.Context, request GetWorkflowRunRequestObject) (GetWorkflowRunResponseObject, error)

	// (POST /api/v1/workflows/{name}/runs/{id}/steps/{step}/continue)
	ContinueWorkflowStep(ctx context.Context, request ContinueWorkflowStepRequestObject) (ContinueWorkflowStepResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

